table.sort(Po.kinds,function(Uo,Vo)
return Uo.name<Vo.name
end)
local Wo=eb.team()
local Xo=Ko.profile_data.collection.owned_units
for Yo,Zo in ipairs(Po.kinds)do
for _o,ap in pairs(Xo)do
if eb.skinFits(ap.unit_id,Zo.skin)then
Zo.fits=true
break
end
end
local bp=Zo.rarity==Byc[1756]or Zo.rarity==Byc[1757]
Zo.keep=(Zo.fits or bp)and 1 or 0
for cp=Zo.keep+1,#Zo.uuids do
table.insert(Po.sell,{uuid=Zo.uuids[cp],name=Zo.name,pearls=eb.SKIN_PRICE[Zo.rarity]or 0})
Po.pearls=Po.pearls+(eb.SKIN_PRICE[Zo.rarity]or 0)
end
end
for dp,ep in ipairs(Wo)do
local fp=ep.skin and ep.skin._skin_id and Mo[ep.skin._skin_id]
if not(fp and fp._skin_set==eb.SKIN_SET)then
for gp,ip in pairs(Mo)do
if type(ip)==Byc[1497]and ip._skin_set==eb.SKIN_SET and eb.skinFits(ep.unit_id,ip)then
local jp=gp..Byc[1758]
if Oo[jp]then
table.insert(Po.wear,{uuid=Oo[jp].uuids[1],unit=ep.uuid,unitName=N.name(ep.unit_id),name=Oo[jp].name})
else
table.insert(Po.missing,{item=jp,unitName=N.name(ep.unit_id),name=ip.name,boost=tonumber(ip._damage_boost)or 0,drop=eb.SKIN_DROP[ip._skin_rarity]or 0})
end
end
end
end
end
return Po
end
function eb.starPlan(kp)
