rp[vp.evolved.from]=true
end
end
for wp,yp in pairs(lp.usage and lp.usage.possible_rewards or{})do
local zp=yp.unit or yp.item
if zp and H.Units[zp]and H.Units[zp].rarity==Byc[1757]and not rp[zp]then
table.insert(pp.units,N.name(zp))
end
end
table.sort(pp.units)
local Ap={}
if#kp.missing>0 then
local Bp=kp.missing[1]
table.insert(Ap,string.format(Byc[1759],Bp.name,Bp.unitName))
end
if#pp.units>0 then
table.insert(Ap,string.format(Byc[1760],table.concat(pp.units,Byc[1593])))
end
pp.why=table.concat(Ap,Byc[1761])
pp.open= #Ap>0 and math.min(pp.can,#pp.units>0 and pp.left or 100)or 0
