function db.gainXp(xK,yK)
local zK,AK=tonumber(xK.xp)or 0,db.xpFor(xK.unit_id,db.cap(xK))
local BK=math.max(0,AK-zK)
if BK<=0 or(yK or 0)<=0 then
return 0,0
end
local CK=math.min(yK,BK)
local DK=db.base(xK)
if DK<=0 then
return 0,CK
end
return db.share(xK.unit_id)*(db.score(db.whatIf(xK,{xp=zK+CK}))/DK-1)*100,CK
end
function db.gainFuse(EK)
if db.lb(EK)>=1 then
return 0
end
local FK=db.base(EK)
if FK<=0 then
return 0
end
local GK=db.whatIf(EK,{xp=math.max(tonumber(EK.xp)or 0,db.xpFor(EK.unit_id,110)),further_modifiers={limit_break={current_limit_break=1}}})
return db.share(EK.unit_id)*(db.score(GK)/FK-1)*100+5
end
