end
local wO=fO.collection:get_unit_by_uuid(eO.uuid)or gO
local xO=(tonumber(wO.xp)or 0)-rO
if xO>0 then
R.add(string.format(Byc[2149],mO,eO.name),mO,Byc[2150],string.format(Byc[2151],M.fmt(xO),sO,db.level(wO)))
