function V.upgradeGain(P9,Q9,R9,S9,T9,U9)
local V9,W9=Q9[R9],Q9[R9+1]
local X9=(V9 .cd>0 and V9 .damage/V9 .cd or 0)
local Y9=(W9 .cd>0 and W9 .damage/W9 .cd or 0)*N.aoe(W9 .atk,W9 .range)/math.max(0.3,N.aoe(V9 .atk,V9 .range))
local Z9=X9>0 and P9*(Y9/X9-1)or(U9 or 0)
local _9=Q9[R9+2]
if _9 and R9+1<Q9 .max and _9 .cd>0 and W9 .cd>0 and X9>0 then
local aab=P9*((_9 .damage/_9 .cd)/X9-1)
local bab=S9+_9 .cost*T9
if aab/bab>Z9/S9 then
Z9=Z9+(aab/bab*S9-Z9)*0.5
end
end
local cab=(W9 .range or 0)>(V9 .range or 0)and(1+((W9 .range-V9 .range)/math.max(1,V9 .range)))or 1
return math.max(0,Z9)*cab
end
function V.dpsFor(dab,eab)
if eab<=0 then
return 0
end
local fab={}
for gab,hab in ipairs(dab)do
if not hab.farm and hab.gain>0 then
table.insert(fab,hab)
end
end
table.sort(fab,function(iab,jab)
return iab.gain/iab.cost>jab.gain/jab.cost
end)
local kab,lab=0,0
for mab,nab in ipairs(fab)do
if eab<=0 then
break
end
lab=nab.gain/nab.cost
local oab=math.min(1,eab/nab.cost)
kab=kab+nab.gain*oab
eab=eab-nab.cost*oab
end
return kab+math.max(0,eab)*lab*0.7
end
function V.shieldDps(pab,qab,rab,sab,tab,uab,vab)
if(sab or 0)<=0 or(pab or 0)<=0 or(tab or 0)<=0 then
return pab or 0
end
qab,rab,uab=math.max(0.3,qab or 2),math.max(1,rab or 1),uab or 1
local wab=pab*uab*qab/rab
return tab*rab/((sab/math.max(1,vab or 1)+math.max(1,tab/wab))*qab)/uab
end
function V.shieldGain(xab,yab,zab,Aab,Bab,Cab,Dab,Eab)
local Fab,Gab=N.attackInfo(yab.atk,yab.range),N.attackInfo(Aab.atk,Aab.range)
local Hab=V.shieldDps(xab,(tonumber(yab.cd)or 2)*(Dab or 1),Fab.n,Bab,Cab,Eab,Fab.hits)
local Iab=V.shieldDps(zab,(tonumber(Aab.cd)or 2)*(Dab or 1),Gab.n,Bab,Cab,Eab,Gab.hits)
local Jab=math.max(0,((tonumber(Aab.range)or 0)-(tonumber(yab.range)or 0))/math.max(1,tonumber(yab.range)or 1))
return math.max(0,Iab-Hab)+Hab*Jab
end
function V.shieldWork(Kab,Lab,Mab,Nab,Oab,Pab,Qab,Rab,Sab)
if(Nab or 0)<=0 then
return 0
end
local Uab=3*Nab*(Oab or 1)/math.max(1,Pab or 20)
if(Mab or 0)>=Uab then
return 0
end
