end)
for Sqb=1,math.min(4,#Iqb)do
table.insert(rqb,Iqb[Sqb])
end
for Tqb=1,math.min(6,#Jqb)do
table.insert(rqb,Jqb[Tqb].u)
end
end
local Uqb,Vqb={},{}
for Wqb,Xqb in ipairs(rqb)do
