for dEb=0,cEb-1 do
local eEb=_Db:Lerp(aEb,dEb/cEb)
table.insert(Q.samples,{pos=eEb,prog=(YDb+bEb*dEb/cEb)/math.max(1,WDb),lane=RDb.Name})
