local iHb=hHb._stats
if not N.isFarm(iHb.id.Value)and iHb:FindFirstChild(Byc[1634])then
table.insert(fHb,{p=M.flat(hHb:GetPivot().Position),r=iHb.range.Value*(N.SUMMONER[iHb.id.Value]and N.SUMMONER[iHb.id.Value].reach or 1),air=Q.canAir(hHb)})
