for lHb,mHb in ipairs(Q.samples)do
if mHb.prog>kHb then
local nHb=M.flat(mHb.pos)
for oHb,pHb in ipairs(fHb)do
if(nHb-pHb.p).Magnitude<=pHb.r then
if mHb.prog>jHb then
jHb=mHb.prog
