if JHb.hp>0 and JHb.prog>KHb+0.02 and JHb.prog>(FHb or 0)then
FHb,HHb=JHb.prog,Q.laneW and JHb.lane or nil
end
if JHb.hp>0 and JHb.fly and JHb.prog>kHb+0.02 then
GHb=true
end
end
end
local LHb= #fHb>0 and(Q.pressure or 0)>=jHb-0.08
return{covEnd=jHb,airEnd=kHb,leak=FHb,leakLane=HHb,covL=qHb,airLeak=GHb,push=LHb,units= #fHb}
end
