OVb=(NVb and tonumber(OVb)or 15)*((Q.info and tonumber(Q.info.rangeScale))or 1)
local PVb=MVb and I.community and tonumber(JVb.time)and tonumber(JVb.cd)
local function QVb(RVb,SVb)
local TVb=math.floor(RVb*JVb.time/math.max(1,JVb.cd)+0.001)
return math.min(MVb,(1+SVb)^TVb-1)
end
local UVb=0
for VVb,WVb in ipairs(KVb)do
local XVb=0
for YVb,ZVb in ipairs(KVb)do
if(ZVb.pos-WVb.pos).Magnitude<=OVb then
