local bWb,cWb=QVb(ZVb.n,_Vb),ZVb.n+1
while cWb<ZVb.n+6 and QVb(cWb,_Vb)<=bWb+0.001 do
cWb=cWb+1
end
aWb=math.max(0,(QVb(cWb,_Vb)-bWb)/(cWb-ZVb.n))
