function U.searchOf(ojc)
local pjc=J.simTeam[ojc]
if type(pjc)~=Byc[1497]or type(pjc.ids)~=Byc[1497]or os.time()-(tonumber(pjc.at)or 0)>7200 then
return nil
end
local qjc={}
for rjc,sjc in ipairs(Q.team or{})do
qjc[sjc.id]=true
end
local tjc= #pjc.ids>0
for ujc,vjc in ipairs(pjc.ids)do
if not qjc[vjc]then
tjc=false
end
end
return{ids=pjc.ids,won=pjc.won and true or false,wave=pjc.wave,cur=pjc.cur,better=pjc.better and true or nil,played=tjc,ago=os.time()-(tonumber(pjc.at)or 0)}
end
function U.modsOf()
local function wjc(xjc)
local yjc
for zjc,Ajc in pairs(type(xjc)==Byc[1497]and xjc or{})do
yjc=yjc or{}
yjc[zjc]=type(Ajc)==Byc[1498]and math.floor(Ajc*1000+0.5)/1000 or Ajc
end
return yjc
end
local Bjc={}
if Q.mod then
Bjc.weak,Bjc.res,Bjc.strong=wjc(Q.mod.weak),wjc(Q.mod.res),wjc(Q.mod.strong)
end
Bjc.seed=Q.ld._is_daily_challenge and tonumber(Q.ld._challenge_uuid)or nil
local Cjc={}
for Djc,Ejc in pairs(Q.info and Q.info.configs or{})do
local Fjc=type(Ejc)==Byc[1497]and H.Units[Ejc.unit_id]
if type(Fjc)==Byc[1497]then
local Gjc=type(Fjc.enemy_modifiers)==Byc[1497]and Fjc.enemy_modifiers or{}
for Hjc,Ijc in pairs(Gjc)do
if Ijc then
Cjc[Hjc]=(Cjc[Hjc]or 0)+1
end
end
if not Gjc.Flying and W.flies(Fjc)then
Cjc.Flying=(Cjc.Flying or 0)+1
end
end
end
if next(Cjc)then
Bjc.enemy=Cjc
end
for Jjc,Kjc in ipairs({Byc[2709],Byc[2710],Byc[1727]})do
local Ljc=J.enemyMods[Kjc]
local Mjc=W.modRead(Ljc)
if Mjc then
Bjc.measured=Bjc.measured or{}
Bjc.measured[Kjc]={f=math.floor(Mjc*1000+0.5)/1000,n= #Ljc.r}
end
end
